import { chromium, expect } from '@playwright/test'
const browser=await chromium.launch({executablePath:process.env.WARDAH_BROWSER_EXECUTABLE||undefined,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']})
const errors=[]; const pages=[]
const state=page=>page.evaluate(async()=> (await fetch('/state')).json())
const business=s=>Object.fromEntries(Object.entries(s).filter(([k])=>k!=='trace'))
const financial=s=>Object.fromEntries(['stage_wip_log','material_consumption','bins','stock_ledger_entries','products','gl_entries','gl_entry_lines','journal_entries','journal_lines'].map(k=>[k,s[k]]))
const calls=(s,name)=>s.trace.filter(r=>r.name===name)
async function open(path) {
 const context=await browser.newContext()
 await context.route('**/*',route=>new URL(route.request().url()).hostname==='127.0.0.1'?route.continue():route.abort())
 const page=await context.newPage(); pages.push(page)
 page.on('pageerror',e=>errors.push(e.message))
 page.on('console',e=>{if(e.type()==='error') errors.push(e.text())})
 await page.goto('http://127.0.0.1:4177'+path)
 return {context,page}
}
async function fill(page,mo,s) {
 await expect(page.getByLabel('Manufacturing order',{exact:true})).toBeEnabled()
 await page.getByLabel('Manufacturing order',{exact:true}).selectOption(mo.id)
 const res=s.material_reservations.find(r=>r.mo_id===mo.id)
 const wo=s.work_orders.find(r=>r.mo_id===mo.id)
 const wip=s.stage_wip_log.find(r=>r.mo_id===mo.id)
 for(const [label,value] of [['Stage',wip.stage_id],['Reserved material 1',res.id],['Work order 1',wo.id],['Warehouse 1','ed000000-0000-4000-8000-0000000000e1'],['Base unit 1',res.uom_id]]) {
  await expect(page.getByLabel(label,{exact:true})).toBeEnabled()
  await page.getByLabel(label,{exact:true}).selectOption(value)
 }
 await page.getByLabel('Quantity 1',{exact:true}).fill('10')
 await expect(page.getByRole('button',{name:'Issue materials',exact:true})).toBeEnabled()
}
async function inspect(page,order) {
 await order.getByRole('button',{name:'Record inspection',exact:true}).click()
 const form=page.getByRole('dialog')
 await expect(form.getByLabel('Accepted quantity',{exact:true})).toHaveValue('')
 await expect(form.getByRole('combobox',{name:'Inspection type',exact:true})).toContainText('Final')
 await form.getByLabel('Accepted quantity',{exact:true}).fill('5')
 return form
}
try {
 const material=await open('/'); const qc=await open('/quality?actor=qc'); const stale=await open('/')
 const page=material.page; const quality=qc.page
 await expect(quality.getByRole('heading',{name:'Quality Control',exact:true})).toBeVisible()
 const initial=await state(page)
 expect(initial.database).toMatch(/^wardah_issue_parent_198_canonical_qc199_browser_/)
 const mo=initial.manufacturing_orders.find(r=>r.order_number==='ISSUE-SCOPE-1')
 const order=quality.getByRole('row').filter({has:quality.getByRole('cell',{name:mo.order_number,exact:true})}).first()
 await expect(order.getByRole('button',{name:'Place under inspection',exact:true})).toBeVisible()
 await fill(page,mo,initial); await fill(stale.page,mo,initial)
 await page.evaluate(()=>localStorage.setItem('operator:lose-issue','true'))
 await page.getByRole('button',{name:'Issue materials',exact:true}).click()
 await expect(page.getByRole('button',{name:'Retry saved event',exact:true})).toBeEnabled()
 const posted=await state(page)
 expect(posted.material_consumption.filter(r=>r.mo_id===mo.id)).toHaveLength(1)
 const receipt=posted.material_issue_events.find(r=>r.mo_id===mo.id)
 expect(receipt).toBeTruthy()
 expect(posted.manufacturing_orders.find(r=>r.id===mo.id).maintenance_version).toBe(mo.maintenance_version)
 await order.getByRole('button',{name:'Place under inspection',exact:true}).click()
 await expect(order.getByRole('cell',{name:'Under inspection',exact:true})).toBeVisible()
 const held=await state(page)
 expect(held.manufacturing_orders.find(r=>r.id===mo.id).maintenance_version).toBe(mo.maintenance_version+1)
 expect(financial(held)).toEqual(financial(posted))
 await page.getByRole('button',{name:'Retry saved event',exact:true}).click()
 await expect(page.getByRole('status').filter({hasText:'Issue confirmed. Receipt:'}).locator('code')).toHaveText(receipt.event_id)
 const replay=await state(page)
 expect(business(replay)).toEqual(business(held))
 const issueCalls=calls(replay,'rpc_consume_material_event')
 expect(issueCalls).toHaveLength(2); expect(issueCalls[1].args).toEqual(issueCalls[0].args)
 expect(issueCalls[1].data).toEqual(issueCalls[0].data)
 console.log('QC_MATERIAL_BROWSER_RECEIPT_REPLAY_DURING_HOLD_PASS')
 // A second browser's already-mounted form sends new intent after QC commits.
 await stale.page.getByRole('button',{name:'Issue materials',exact:true}).click()
 await expect(stale.page.getByRole('button',{name:'Retry saved event',exact:true})).toBeEnabled()
 const refused=await state(page)
 expect(calls(refused,'rpc_consume_material_event').at(-1).error).toEqual({code:'P0001',message:'MANUFACTURING_ORDER_NOT_IN_PROGRESS'})
 expect(business(refused)).toEqual(business(held))
 console.log('QC_MATERIAL_BROWSER_STALE_FORM_NEW_EVENT_REFUSED_PASS')
 const form=await inspect(quality,order)
 await quality.evaluate(()=>localStorage.setItem('operator:lose-inspection','true'))
 await form.getByRole('button',{name:'Record inspection',exact:true}).click()
 await expect(quality.getByText('The operation could not be completed.',{exact:true})).toBeVisible()
 const recorded=await state(page)
 const inspection=recorded.quality_inspections.find(r=>r.mo_id===mo.id)
 expect(inspection).toBeTruthy(); expect(inspection.inspector_id).toBe('ed000000-0000-4000-8000-0000000000a3'); expect(inspection.qc_cycle).toBe(1)
 expect(recorded.manufacturing_orders.find(r=>r.id===mo.id).maintenance_version).toBe(mo.maintenance_version+1)
 expect(financial(recorded)).toEqual(financial(held))
 await form.getByRole('button',{name:'Record inspection',exact:true}).click()
 await expect(form).toHaveCount(0)
 await expect(order.getByText('Ready (5)',{exact:true})).toBeVisible()
 const inspectionReplay=await state(page)
 expect(business(inspectionReplay)).toEqual(business(recorded))
 const inspections=calls(inspectionReplay,'rpc_record_quality_inspection')
 expect(inspections).toHaveLength(2); expect(inspections[1].args).toEqual(inspections[0].args); expect(inspections[1].data.replayed).toBe(true)
 expect(Object.keys(inspections[0].args).sort()).toEqual(['p_mo_id','p_payload','p_request_id'])
 await expect(quality.getByRole('cell',{name:inspection.inspection_number,exact:true})).toBeVisible()
 console.log('QC_MATERIAL_BROWSER_FINAL_INSPECTION_LOST_RESPONSE_REPLAY_PASS')
 await order.getByRole('button',{name:'Return to production',exact:true}).click()
 const returning=quality.getByRole('dialog')
 await expect(returning.getByRole('button',{name:'Return to production',exact:true})).toBeDisabled()
 await returning.getByLabel('Reason (required)',{exact:true}).fill('Native M199 paired proof')
 await returning.getByRole('button',{name:'Return to production',exact:true}).click()
 await expect(returning).toHaveCount(0)
 await expect(order.getByRole('cell',{name:'In progress',exact:true})).toBeVisible()
 const returned=await state(page)
 expect(returned.manufacturing_orders.find(r=>r.id===mo.id).maintenance_version).toBe(mo.maintenance_version+2)
 expect(financial(returned)).toEqual(financial(recorded))
 // Start a clean profile; the rejected intent remains immutable in the old one.
 const refreshed=await open('/'); await fill(refreshed.page,mo,returned)
 await refreshed.page.getByRole('button',{name:'Issue materials',exact:true}).click()
 await expect(refreshed.page.getByText('Issue confirmed. Receipt:',{exact:false})).toBeVisible()
 const resumed=await state(page)
 expect(resumed.material_consumption.filter(r=>r.mo_id===mo.id)).toHaveLength(2)
 expect(resumed.stock_ledger_entries.length-initial.stock_ledger_entries.length).toBe(2)
 expect(resumed.manufacturing_orders.find(r=>r.id===mo.id).maintenance_version).toBe(mo.maintenance_version+2)
 console.log('QC_MATERIAL_BROWSER_RETURN_NEW_CONSUMPTION_PASS')
 await order.getByRole('button',{name:'Place under inspection',exact:true}).click()
 await expect(order.getByRole('cell',{name:'Under inspection',exact:true})).toBeVisible()
 await expect(order.getByText('Not ready',{exact:true})).toBeVisible()
 const cycle2=await state(page)
 expect(cycle2.mo_quality_cycles.find(r=>r.mo_id===mo.id).cycle).toBe(2)
 const deniedForm=await inspect(quality,order)
 await quality.evaluate(async()=>{await fetch('/fixture-grants',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:'manufacturing.quality_inspections.create',enabled:false})})})
 const preDenial=await state(page)
 await deniedForm.getByRole('button',{name:'Record inspection',exact:true}).click()
 await expect(quality.getByText('You do not have permission to record inspections.',{exact:true})).toBeVisible()
 const deniedInspection=await state(page)
 expect(calls(deniedInspection,'rpc_record_quality_inspection').at(-1).error).toEqual({code:'42501',message:'QUALITY_INSPECT_PERMISSION_DENIED'})
 expect(business(deniedInspection)).toEqual(business(preDenial))
 await quality.evaluate(async()=>{await fetch('/fixture-grants',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:'manufacturing.quality_inspections.create',enabled:true})})})
 await deniedForm.getByRole('button',{name:'Record inspection',exact:true}).click()
 await expect(deniedForm).toHaveCount(0)
 const final=await state(page)
 expect(final.quality_inspections.filter(r=>r.mo_id===mo.id)).toHaveLength(2)
 expect(financial(final)).toEqual(financial(resumed))
 console.log('QC_MATERIAL_BROWSER_NEW_CYCLE_REVOKED_GRANT_NO_EFFECTS_PASS')
 expect(errors).toEqual([])
 if(process.env.WARDAH_QC_OUTPUT) await quality.screenshot({path:process.env.WARDAH_QC_OUTPUT+'/native-quality.png',fullPage:true})
 console.log('QC_MATERIAL_BROWSER_199_PASS proofs=5 profiles=4 database='+final.database+' identity=simulated')
 for(const c of [material,qc,stale,refreshed]) await c.context.close()
} catch(e) { console.error('BROWSER_ERRORS',JSON.stringify(errors)); if(pages[0]) console.error('RPC_DIAGNOSTICS',JSON.stringify((await state(pages[0])).trace.slice(-8))); throw e }
finally { await browser.close() }
